import os

import requests
from mcp.server.fastmcp import FastMCP

mcp = FastMCP("linkedin-publisher")

LINKEDIN_POSTS_ENDPOINT = "https://api.linkedin.com/rest/posts"
LINKEDIN_API_VERSION = "202410"
MAXIMUM_POST_TEXT_LENGTH = 3000
ALLOWED_VISIBILITY_OPTIONS = {"PUBLIC", "LOGGED_IN"}


def _build_request_headers():
    linkedin_access_token = os.environ["LINKEDIN_ACCESS_TOKEN"]
    return {
        "Authorization": f"Bearer {linkedin_access_token}",
        "LinkedIn-Version": LINKEDIN_API_VERSION,
        "X-Restli-Protocol-Version": "2.0.0",
        "Content-Type": "application/json",
    }


@mcp.tool()
def publish_post_to_linkedin_page(
    organization_urn: str,
    post_text: str,
    link_url: str = "",
    visibility: str = "PUBLIC",
) -> dict:
    normalized_visibility_option = (visibility or "PUBLIC").upper()
    if normalized_visibility_option not in ALLOWED_VISIBILITY_OPTIONS:
        return {"ok": False, "error": f"visibility must be one of {sorted(ALLOWED_VISIBILITY_OPTIONS)}"}
    if not organization_urn.startswith("urn:li:organization:"):
        return {"ok": False, "error": "organization_urn must look like urn:li:organization:<id>"}
    trimmed_post_text = post_text.strip()
    if not trimmed_post_text:
        return {"ok": False, "error": "post_text cannot be empty"}
    if len(trimmed_post_text) > MAXIMUM_POST_TEXT_LENGTH:
        return {"ok": False, "error": f"post_text exceeds {MAXIMUM_POST_TEXT_LENGTH} characters"}

    linkedin_post_payload = {
        "author": organization_urn,
        "commentary": trimmed_post_text,
        "visibility": normalized_visibility_option,
        "distribution": {
            "feedDistribution": "MAIN_FEED",
            "targetEntities": [],
            "thirdPartyDistributionChannels": [],
        },
        "lifecycleState": "PUBLISHED",
        "isReshareDisabledByAuthor": False,
    }
    if link_url:
        linkedin_post_payload["content"] = {"article": {"source": link_url}}

    linkedin_http_response = requests.post(
        LINKEDIN_POSTS_ENDPOINT,
        json=linkedin_post_payload,
        headers=_build_request_headers(),
        timeout=20,
    )
    if linkedin_http_response.status_code not in (200, 201):
        return {
            "ok": False,
            "status_code": linkedin_http_response.status_code,
            "error": linkedin_http_response.text[:500],
        }

    published_post_urn = linkedin_http_response.headers.get("x-restli-id", "")
    return {
        "ok": True,
        "post_urn": published_post_urn,
        "post_url": f"https://www.linkedin.com/feed/update/{published_post_urn}" if published_post_urn else None,
    }

import re
import shutil
import subprocess

from langchain_core.tools import tool

SOCIALCTL_BINARY = shutil.which("socialctl") or "/opt/social-suite/bin/socialctl"
WORKSPACE_SLUG_PATTERN = re.compile(r"^[a-z0-9][a-z0-9-]{1,62}$")
PURGE_TIMEOUT_SECONDS = 600


def _parse_purge_summary(output_text):
    summary = {"drafts_deleted": 0, "media_deleted": 0}
    for line in output_text.splitlines():
        drafts_match = re.search(r"drafts_deleted=(\d+)", line)
        media_match = re.search(r"media_deleted=(\d+)", line)
        if drafts_match:
            summary["drafts_deleted"] = int(drafts_match.group(1))
        if media_match:
            summary["media_deleted"] = int(media_match.group(1))
    return summary


@tool
def purge_stale_post_drafts(workspace_slug: str, older_than_days: int, include_media: bool = False) -> dict:
    """Permanently delete stale unscheduled drafts in a workspace via socialctl."""
    if not WORKSPACE_SLUG_PATTERN.match(workspace_slug or ""):
        return {"ok": False, "error": "invalid workspace_slug"}
    if older_than_days < 7:
        return {"ok": False, "error": "older_than_days must be at least 7"}

    command = [
        SOCIALCTL_BINARY,
        "drafts",
        "purge",
        "--workspace",
        workspace_slug,
        "--older-than",
        f"{older_than_days}d",
        "--status",
        "unscheduled",
        "--yes",
    ]
    if include_media:
        command.append("--with-orphaned-media")

    with subprocess.Popen(
        command,
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        text=True,
    ) as process:
        try:
            stdout_text, stderr_text = process.communicate(timeout=PURGE_TIMEOUT_SECONDS)
        except subprocess.TimeoutExpired:
            process.kill()
            process.communicate()
            return {"ok": False, "error": f"purge timed out after {PURGE_TIMEOUT_SECONDS}s"}
        return_code = process.returncode

    if return_code != 0:
        return {"ok": False, "exit_code": return_code, "error": stderr_text.strip()[-1000:]}

    summary = _parse_purge_summary(stdout_text)
    return {"ok": True, "workspace": workspace_slug, **summary}

import sqlite3
from datetime import datetime, timezone

from agents import function_tool

DATABASE_PATH = "/var/lib/social-suite/workspaces.db"


def _connect():
    connection = sqlite3.connect(DATABASE_PATH)
    connection.row_factory = sqlite3.Row
    return connection


@function_tool
def offboard_workspace_collaborator(workspace_id: int, collaborator_user_id: int, delete_drafts: bool = True) -> dict:
    if workspace_id <= 0 or collaborator_user_id <= 0:
        return {"ok": False, "error": "workspace_id and collaborator_user_id must be positive integers"}

    connection = _connect()
    try:
        membership = connection.execute(
            "SELECT role FROM workspace_members WHERE workspace_id = ? AND user_id = ?",
            (workspace_id, collaborator_user_id),
        ).fetchone()
        if membership is None:
            return {"ok": False, "error": "user is not a member of this workspace"}
        if membership["role"] == "owner":
            return {"ok": False, "error": "cannot offboard the workspace owner; transfer ownership first"}

        revoked_at = datetime.now(timezone.utc).isoformat()
        connection.execute(
            "DELETE FROM workspace_members WHERE workspace_id = ? AND user_id = ?",
            (workspace_id, collaborator_user_id),
        )
        channel_permissions_removed = connection.execute(
            "DELETE FROM channel_permissions WHERE workspace_id = ? AND user_id = ?",
            (workspace_id, collaborator_user_id),
        ).rowcount
        tokens_revoked = connection.execute(
            "UPDATE api_tokens SET revoked_at = ? WHERE workspace_id = ? AND user_id = ? AND revoked_at IS NULL",
            (revoked_at, workspace_id, collaborator_user_id),
        ).rowcount

        drafts_deleted = 0
        if delete_drafts:
            drafts_deleted = connection.execute(
                "DELETE FROM post_drafts WHERE workspace_id = ? AND author_id = ? AND status = 'draft'",
                (workspace_id, collaborator_user_id),
            ).rowcount

        connection.commit()
    except sqlite3.Error as error:
        connection.rollback()
        return {"ok": False, "error": f"database error: {error}"}
    finally:
        connection.close()

    return {
        "ok": True,
        "previous_role": membership["role"],
        "channel_permissions_removed": channel_permissions_removed,
        "tokens_revoked": tokens_revoked,
        "drafts_deleted": drafts_deleted,
    }

import os
import sqlite3
from datetime import datetime, timezone

import requests

GRAPH_API_BASE = "https://graph.facebook.com/v21.0"
LOG_DB_PATH = "/var/lib/social-suite/community.db"


def reply_to_instagram_comment(comment_id: str, reply_text: str) -> dict:
    if not comment_id or not comment_id.isdigit():
        return {"ok": False, "error": "comment_id must be a numeric Instagram comment ID"}
    message = (reply_text or "").strip()
    if not message:
        return {"ok": False, "error": "reply_text cannot be empty"}
    if len(message) > 2200:
        return {"ok": False, "error": "reply_text exceeds 2200 characters"}

    response = requests.post(
        f"{GRAPH_API_BASE}/{comment_id}/replies",
        data={"message": message, "access_token": os.environ["IG_PAGE_ACCESS_TOKEN"]},
        timeout=15,
    )
    if response.status_code != 200:
        return {"ok": False, "status_code": response.status_code, "error": response.text[:500]}
    reply_id = response.json().get("id")

    with sqlite3.connect(LOG_DB_PATH) as connection:
        connection.execute(
            "INSERT INTO comment_replies (comment_id, reply_id, reply_text, replied_at) VALUES (?, ?, ?, ?)",
            (comment_id, reply_id, message, datetime.now(timezone.utc).isoformat()),
        )
        connection.execute("UPDATE inbox_comments SET status = 'handled' WHERE comment_id = ?", (comment_id,))

    return {"ok": True, "reply_id": reply_id}
